// ============ v5 Match SKUs & Build Rows (multi-supplier) ============
// Per-supplier sub-workflow. Inputs come from Workflow Trigger payload.
// Generalizes v4's Gavin-only logic: column-position-based Amount Ref read,
// per-supplier Walkin format switch, dedup-against-Shopify, Luxon date parsing,
// per-supplier title hints + exclude SKUs from Registry row.

const { DateTime } = require('luxon');

// ----- helpers -----
function parsePrice(s) {
  if (s === undefined || s === null || s === '') return 0;
  const m = String(s).replace(/[$,\s]/g, '').match(/-?\d+(?:\.\d+)?/);
  return m ? parseFloat(m[0]) : 0;
}
function escRegex(s) { return s.replace(/[.+?^${}()|[\]\\]/g, '\\$&'); }
function fmtSGD(n) { return '$' + Number(n).toFixed(2); }
const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
// TZ-SAFE: format in Asia/Singapore explicitly. Do NOT use d.getDate()/getMonth()
// -- those read the PROCESS timezone, and the n8n JS Task Runner (default since
// 2.22.5) runs as a separate process that does NOT inherit TZ from the container,
// so it evaluates as UTC. That silently shifted every timestamp before 08:00 SGT
// back by one day (e.g. an order at 1 Jul 07:30 SGT rendered as '30 Jun 2026').
// SGT is UTC+8 year-round with no DST, so +8h then reading UTC parts is exact.
function fmtDate(d) {
  if (!d || isNaN(d.getTime())) return '';
  const sgt = new Date(d.getTime() + 8 * 3600 * 1000);
  return sgt.getUTCDate() + ' ' + MON[sgt.getUTCMonth()] + ' ' + sgt.getUTCFullYear();
}
function parseDate(str, primaryFmt) {
  if (!str) return null;
  const trimmed = String(str).trim();
  if (!trimmed) return null;
  const tries = [primaryFmt, 'd LLL yyyy', 'd LLLL yyyy', 'd-LLLL-yy', 'd/LL/yy', 'd LLL yy', 'd-LLL-yy'];
  for (const f of tries) {
    if (!f) continue;
    const dt = DateTime.fromFormat(trimmed, f, { zone: 'Asia/Singapore' });
    if (dt.isValid) return dt.toJSDate();
  }
  return null;
}
function toSgdStr(v) {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'number') return '$' + v.toFixed(2);
  const s = String(v).trim();
  if (s.startsWith('$') || s.startsWith('-$')) return s;
  if (/^-?\d+(\.\d+)?$/.test(s)) return '$' + parseFloat(s).toFixed(2);
  return s;
}

// ----- Inputs -----
const trigger = $('Workflow Trigger').first().json;
const supplier = trigger.supplier || {};
const orders = trigger.orders || [];
const params = trigger.params || {};
const monthStart = new Date(params.MONTH_START_ISO);
const monthEnd = new Date(params.MONTH_END_ISO);
const takehomeCol = (supplier.supplier_name || 'Supplier') + ' Amount (Takehome)';

// ----- Amount Reference -----
// First 3 cols always have stable headers (SKU, Listing Price, 3DPS + Stripe Fee (3.4%)).
// Takehome col header varies per supplier (Piggy/Stan/Bryan/etc Amount/SGD (Takehome)) so read positionally.
// Sheets node v4.4 prepends 'row_number' key — filter it out before positional access.
const refRows = $('Read Amount Reference').all().map(it => it.json);
const masters = [];
for (const r of refRows) {
  const sku = String(r['SKU'] || '').trim();
  if (!sku || sku.toLowerCase() === 'sku') continue;
  const listing = parsePrice(r['Listing Price']);
  const fee = parsePrice(r['3DPS + Stripe Fee (3.4%)']);
  const colsNoRowNum = Object.keys(r).filter(k => k !== 'row_number');
  const takehomeKey = colsNoRowNum[3];
  const takehome = parsePrice(r[takehomeKey]);
  // Treat _ and - as interchangeable so 'bbgb_heavy_blue_gels' also matches 'bbgb-heavy-blue-gels'
  const pat = '^' + escRegex(sku).replace(/COLOUR|XXX/g, '.+').replace(/[-_]/g, '[-_]') + '$';
  masters.push({ sku, listing, fee, takehome, re: new RegExp(pat, 'i') });
}
function findMaster(sku) {
  if (!sku) return null;
  for (const m of masters) if (m.re.test(sku)) return m;
  return null;
}

// ----- Per-supplier exclude SKUs and title hints (from Registry row) -----
const excludeStr = supplier.exclude_skus || '';
const excludeRegexes = excludeStr.split(',').map(s => s.trim()).filter(Boolean).map(p =>
  new RegExp('^' + escRegex(p).replace(/\\\*/g, '.*') + '$', 'i')
);
function isExcluded(sku) { return sku && excludeRegexes.some(re => re.test(sku)); }

const titleHintsArr = (supplier.title_hints || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
// Returns null when nothing fires, else { weak, why } where `why` names every field
// that matched and the exact hint text (e.g. "note:'linford','vitae'"). The match is
// deliberately NOT dropped: a labelled false positive is cheaper to filter out than a
// silently missing payout row. Remarks is the only place a human can audit this later.
function titleHints(li, o) {
  if (titleHintsArr.length === 0) return null;
  // Skip property fields that look like customer contact info — value contains @ (email)
  // or name mentions email/phone/address/contact. These commonly contain customer names
  // that produce false positives (e.g. 'bryancheong6155@gmail.com' matching hint 'bryan').
  const filteredProps = (li.properties || []).filter(p => {
    const n = String(p.name || '').toLowerCase();
    const v = String(p.value || '');
    if (/email|phone|address|contact|name/.test(n)) return false;
    if (v.includes('@')) return false;
    return true;
  });
  // Product fields describe the item itself. note/tags are free-text logistics typed by
  // staff and are a known false-positive source — an order note reading 'to be picked up
  // by linford of vitae precision' pulled three SweetHeart magnets into Vitae's Aug 2026
  // tab. Both still match; a match resting ONLY on note/tags is labelled WEAK so it can
  // be filtered in the sheet.
  const PRODUCT_FIELDS = ['title', 'variant', 'name', 'vendor', 'props'];
  const fields = [
    ['title',   li.title || ''],
    ['variant', li.variant_title || ''],
    ['name',    li.name || ''],
    ['vendor',  li.vendor || ''],
    ['props',   filteredProps.map(p => (p.name || '') + ' ' + (p.value || '')).join(' ')],
    ['note',    o && o.note ? o.note : ''],
    ['tags',    o && o.tags ? o.tags : ''],
  ];
  const fired = [];
  for (const pair of fields) {
    const low = String(pair[1]).toLowerCase();
    const hits = titleHintsArr.filter(h => low.includes(h));
    if (hits.length) fired.push([pair[0], hits]);
  }
  if (fired.length === 0) return null;
  // li.name is title + ' - ' + variant, so it re-reports whatever those already matched.
  // Only surface it when it contributes a hint of its own.
  const fromTitleVariant = new Set();
  for (const f of fired) if (f[0] === 'title' || f[0] === 'variant') for (const h of f[1]) fromTitleVariant.add(h);
  const shown = fired.filter(f => f[0] !== 'name' || f[1].some(h => !fromTitleVariant.has(h)));
  return {
    weak: !fired.some(f => PRODUCT_FIELDS.indexOf(f[0]) !== -1),
    why: shown.map(f => f[0] + ":'" + f[1].join("','") + "'").join(' '),
  };
}

// ----- Existing dest rows for dedup -----
const existingItems = $('Read Existing Destination Rows').all();
const existingRows = existingItems.map(it => it.json).filter(r => r && Object.keys(r).length > 0);
const existingKeys = new Set();
for (const r of existingRows) {
  const on = String(r['Order No.'] || r['OrderNo.'] || r['OrderNo'] || '').trim();
  const sku = String(r['SKU'] || '').trim();
  const k = on + '|' + sku;
  if (k !== '|') existingKeys.add(k);
  // Composite key (orderNo|sku|takehome) for manual rows with shared orderNo+sku but different amounts
  // (e.g. multiple 'fedex shipping' deductions in one month). Read takehome positionally — col 8 after row_number filter.
  const keysNoRowNum = Object.keys(r).filter(k2 => k2 !== 'row_number');
  const takehomeKey = keysNoRowNum[8];
  const takehomeVal = takehomeKey ? String(r[takehomeKey] || '').trim() : '';
  const compositeKey = on + '|' + sku + '|' + takehomeVal;
  if (compositeKey !== '||') existingKeys.add(compositeKey);
}

// ----- Stats accumulator -----
const stats = {
  supplier_name: supplier.supplier_name || '',
  shopify_orders: orders.length,
  shopify_line_items: 0,
  rows_built: 0,
  duplicates_skipped: 0,
  flagged_currency: 0,
  flagged_refund: 0,
  flagged_underprice: 0,
  flagged_title_match: 0,
  walkin_rows_total: 0,
  walkin_rows_in_month: 0,
  walkin_rows_kept: 0,
  walkin_deduped_against_shopify: 0,
};

const outRows = [];
const shopifyOrderNoSet = new Set();

// ----- Process Shopify orders against THIS supplier's Amount Ref -----
for (const o of orders) {
  const orderNo = o.order_number != null ? String(o.order_number) : String(o.name || '').replace('#','');
  shopifyOrderNoSet.add(orderNo);
  for (const li of (o.line_items || [])) {
    stats.shopify_line_items++;
    // Check exclude against the same fallback used for the SKU column (handles items with no Shopify SKU)
    const skuForCheck = li.sku || li.title || li.name || '';
    if (isExcluded(skuForCheck)) continue;
    const master = findMaster(li.sku);
    const hintHit = master ? null : titleHints(li, o);
    if (!master && !hintHit) continue;

    const flags = [];
    const orderCcy = (o.currency || '').toUpperCase();
    if (orderCcy !== 'SGD') {
      flags.push('CURRENCY: ' + (o.currency || 'unknown'));
      stats.flagged_currency++;
    }
    if (Array.isArray(o.refunds) && o.refunds.length > 0) {
      flags.push('REFUND - verify');
      stats.flagged_refund++;
    }
    if (o.cancelled_at) {
      flags.push('CANCELLED - verify');
      if (!stats.flagged_cancelled) stats.flagged_cancelled = 0;
      stats.flagged_cancelled++;
    }

    const firstName = (o.customer && o.customer.first_name) || '';
    const lastName  = (o.customer && o.customer.last_name)  || '';
    const name = (firstName + ' ' + lastName).trim() || 'Guest';
    const dateFmt = fmtDate(new Date(o.created_at));
    const email   = o.email || '';
    const qty     = li.quantity || 1;

    const liShopPrice = li.price_set && li.price_set.shop_money
      ? parseFloat(li.price_set.shop_money.amount || 0)
      : parseFloat(li.price || 0);

    let listing, fee, takehome;
    if (master) {
      const refUnfilled = master.listing < 0.01;  // ref listing not yet filled in (e.g., Vitae draft state)
      if (refUnfilled) {
        // Ref price pending — use Shopify sale price for Listing as draft. Yellow-flag for human review.
        flags.push('TITLE MATCH - ref price pending [ref:' + master.sku + ']'
          + (li.vendor ? ' vendor="' + li.vendor + '"' : ''));
        stats.flagged_title_match++;
        listing = liShopPrice; fee = null; takehome = liShopPrice;
      } else if (orderCcy === 'SGD' && liShopPrice < master.listing - 0.01) {
        // Underprice (SGD only — foreign-currency prices not directly comparable)
        flags.push('UNDERPRICED: shopify=$' + liShopPrice.toFixed(2) + ' listed=$' + master.listing.toFixed(2));
        stats.flagged_underprice++;
        listing = liShopPrice; fee = master.fee; takehome = liShopPrice - master.fee;
      } else {
        listing = master.listing; fee = master.fee; takehome = master.takehome;
      }
    } else {
      // Spell out the evidence so the row can be judged (and filtered) from the sheet
      // alone. 'WEAK' == only the order note/tags matched, no product field did.
      flags.push('TITLE MATCH' + (hintHit.weak ? ' WEAK' : '')
        + ' [' + hintHit.why + ']'
        + (li.vendor ? ' vendor="' + li.vendor + '"' : '')
        + ' - add to Amount Reference?');
      stats.flagged_title_match++;
      if (hintHit.weak) stats.flagged_title_match_weak = (stats.flagged_title_match_weak || 0) + 1;
      // Tentative: assume supplier gets the full listing price (no known IFB fee).
      // Human review will adjust takehome if a fee should apply.
      listing = liShopPrice; fee = null; takehome = liShopPrice;
    }

    // SKU column falls back to title/name when SKU is empty; dedup key must match that same value.
    const skuForRow = li.sku || li.title || li.name || '';
    for (let i = 0; i < qty; i++) {
      const key = orderNo + '|' + skuForRow;
      if (existingKeys.has(key)) { stats.duplicates_skipped++; continue; }
      const row = {
        'Order No.':         orderNo,
        'Date':              dateFmt,
        'Name':              name,
        'Email':             email,
        'Gdrive access':     '',
        'SKU':               skuForRow,
        'Listing Price':     fmtSGD(listing),
        '3DPS+Stripe Fee':   fee !== null ? fmtSGD(fee) : '',
        'Payment Complete':  '',
        'Date of Payment':   '',
        'Remarks':           flags.join(' | '),
      };
      row[takehomeCol] = takehome !== null ? fmtSGD(takehome) : '';
      outRows.push(row);
      stats.rows_built++;
    }
  }
}

// ----- Walkin source: format switch + dedup-against-Shopify -----
const walkinFormat   = supplier.walkin_format   || 'standard-12';
const walkinDateFmt  = supplier.walkin_date_format || 'd LLL yyyy';
const walkinItems    = $('Read Walkin Source').all().map(it => it.json).filter(j => j && Object.keys(j).length > 0);
stats.walkin_rows_total = walkinItems.length;

function gh(r, names) {
  for (const n of names) if (r[n] !== undefined && r[n] !== null && r[n] !== '') return r[n];
  return '';
}
function mapWalkinRow(r, format) {
  if (format === 'standard-12' || format === 'standard-11') {
    return {
      orderNo:  String(gh(r, ['OrderNo.', 'Order No.', 'OrderNo'])),
      date:     String(gh(r, ['Date'])),
      name:     String(gh(r, ['Name'])),
      email:    String(gh(r, ['Email'])),
      gdrive:   format === 'standard-12' ? String(gh(r, ['Gdrive access'])) : '',
      sku:      String(gh(r, ['SKU'])),
      listing:  gh(r, ['Listing Price']),
      fee:      gh(r, ['3DPS + Stripe Fee (3.4%)', '3DPS+Stripe Fee', '3DPS + Stripe Fee', 'Stripe Fee (3.4%)']),
      takehome: gh(r, ['Gavin Amount (Takehome)', 'Piggy Amount (Takehome)', 'Bryan Amount (Takehome)', 'Stan SGD (Takehome)', 'BBSG Amount (Takehome)', 'Dylan Amount (Takehome)']),
      paymentComplete: String(gh(r, ['Payment Complete'])),
      datePayment:     String(gh(r, ['Date of Payment'])),
      remarks:         String(gh(r, ['Remarks'])),
    };
  } else if (format === 'ryan') {
    return {
      orderNo:  String(gh(r, ['Order No.'])),
      date:     String(gh(r, ['Date'])),
      name:     String(gh(r, ['Name'])),
      email:    '',
      gdrive:   '',
      sku:      String(gh(r, ['Item Name'])),
      listing:  gh(r, ['Listing Price']),
      fee:      gh(r, ['IFB + Shopify+ Fee', 'IFB+Shopify+Fee']),
      takehome: gh(r, ['Ryan Take Home']),
      paymentComplete: '',
      datePayment:     '',
      remarks:         String(gh(r, ['Remarks', 'Other Remarks'])),
    };
  } else if (format === 'vitae') {
    return {
      orderNo:  String(gh(r, ['Order No.'])),
      date:     String(gh(r, ['Date'])),
      name:     String(gh(r, ['Customer Name'])),
      email:    '',
      gdrive:   '',
      sku:      String(gh(r, ['Item Name'])),
      listing:  gh(r, ['Listing Price']),
      fee:      gh(r, ['Stripe Fee ($0.5+3.4%)', 'Stripe Fee']),
      takehome: gh(r, ["Linford's ", "Linford's"]),
      paymentComplete: '',
      datePayment:     '',
      remarks:         String(gh(r, ['Other Remarks', 'Remarks'])),
    };
  }
  return null;
}

for (const r of walkinItems) {
  const mapped = mapWalkinRow(r, walkinFormat);
  if (!mapped) continue;

  // Skip 'To pay' / 'Paid' footer summary rows (no SKU, contains pay/total/paid text)
  const footerHaystack = (String(mapped.fee || '') + ' ' + String(mapped.takehome || '') + ' ' + String(mapped.remarks || '')).toLowerCase();
  if (!mapped.sku && /to pay|\btotal\b|paid/.test(footerHaystack)) continue;

  // Manual entries are kept regardless of date filter:
  //   Type A — empty OrderNo + empty Date + SKU + Takehome (e.g. 'fedex shipping' adjustments, refunds)
  //   Type B — OrderNo prefix 'Manual' (backdated entries staff add to a later month)
  // Both surface in dest as orange (non-numeric Order No.) with Remarks 'MANUAL ENTRY' for human review.
  const isManualA = !mapped.orderNo && !mapped.date && mapped.sku && (mapped.takehome || mapped.listing);
  const isManualB = mapped.orderNo && /^manual\b/i.test(mapped.orderNo);
  if (isManualA || isManualB) {
    const orderNo = isManualA ? 'Manual' : mapped.orderNo;
    const dedupKey = orderNo + '|' + mapped.sku + '|' + toSgdStr(mapped.takehome);
    if (existingKeys.has(dedupKey)) { stats.duplicates_skipped++; continue; }
    const mrow = {
      'Order No.':         orderNo,
      'Date':              mapped.date || '',
      'Name':              mapped.name || '',
      'Email':             mapped.email || '',
      'Gdrive access':     mapped.gdrive || '',
      'SKU':               mapped.sku,
      'Listing Price':     toSgdStr(mapped.listing),
      '3DPS+Stripe Fee':   toSgdStr(mapped.fee),
      'Payment Complete':  mapped.paymentComplete || '',
      'Date of Payment':   mapped.datePayment || '',
      'Remarks':           (mapped.remarks ? mapped.remarks + ' | ' : '') + 'MANUAL ENTRY',
    };
    mrow[takehomeCol] = toSgdStr(mapped.takehome);
    outRows.push(mrow);
    stats.walkin_rows_kept++;
    stats.rows_built++;
    continue;
  }

  const dateObj = parseDate(mapped.date, walkinDateFmt);
  if (!dateObj) continue;
  if (dateObj < monthStart || dateObj > monthEnd) continue;
  stats.walkin_rows_in_month++;

  // Dedup against Shopify pull (handles suppliers who copy Shopify orders into their monthly tab)
  if (mapped.orderNo && shopifyOrderNoSet.has(mapped.orderNo)) {
    stats.walkin_deduped_against_shopify++;
    continue;
  }
  const key = mapped.orderNo + '|' + mapped.sku;
  if (existingKeys.has(key)) { stats.duplicates_skipped++; continue; }

  const row = {
    'Order No.':         mapped.orderNo,
    'Date':              fmtDate(dateObj),
    'Name':              mapped.name,
    'Email':             mapped.email,
    'Gdrive access':     mapped.gdrive,
    'SKU':               mapped.sku,
    'Listing Price':     toSgdStr(mapped.listing),
    '3DPS+Stripe Fee':   toSgdStr(mapped.fee),
    'Payment Complete':  mapped.paymentComplete,
    'Date of Payment':   mapped.datePayment,
    'Remarks':           mapped.remarks,
  };
  row[takehomeCol] = toSgdStr(mapped.takehome);
  outRows.push(row);
  stats.walkin_rows_kept++;
  stats.rows_built++;
}

// ----- Sort by Date ascending -----
function dateKey(s) {
  const d = parseDate(s, 'd LLL yyyy');
  return d ? d.getTime() : 0;
}
outRows.sort((a, b) => dateKey(a['Date']) - dateKey(b['Date']));

// ----- Reorder keys to canonical 12-col output (autoMap uses key insertion order on first run) -----
const orderedRows = outRows.map(r => ({
  'Order No.':         r['Order No.'],
  'Date':              r['Date'],
  'Name':              r['Name'],
  'Email':             r['Email'],
  'Gdrive access':     r['Gdrive access'],
  'SKU':               r['SKU'],
  'Listing Price':     r['Listing Price'],
  '3DPS+Stripe Fee':   r['3DPS+Stripe Fee'],
  [takehomeCol]:       r[takehomeCol],
  'Payment Complete':  r['Payment Complete'],
  'Date of Payment':   r['Date of Payment'],
  'Remarks':           r['Remarks'],
}));

// Stash stats for later nodes
// DEBUG: log key state to help diagnose
const dbg = {
  __debug: true,
  refRows_count: refRows.length,
  refRows_first: refRows[0] || null,
  masters_count: masters.length,
  masters_first: masters[0] ? {sku: masters[0].sku, pat: masters[0].re.toString()} : null,
  walkinItems_count: walkinItems.length,
  walkinItems_first: walkinItems[0] || null,
  takehomeCol,
  supplier_name: supplier.supplier_name,
  amount_ref_tab: supplier.amount_ref_tab_name,
  walkin_format: walkinFormat,
  walkin_date_format: walkinDateFmt,
  stats,
};
console.log('[v5 Match DEBUG]', JSON.stringify(dbg, null, 2));
// If no actual rows matched, emit a single 'NO SALE THIS MONTH' placeholder row so the
// destination tab still gets canonical 12-col headers + a clear visual indicator.
// Dedup against existingKeys so re-runs don't duplicate the placeholder.
if (orderedRows.length === 0) {
  const placeholderKey = '|NO SALE THIS MONTH';
  if (existingKeys.has(placeholderKey)) {
    return []; // already a NO SALE row in dest, don't duplicate
  }
  const placeholder = {
    'Order No.':         '',
    'Date':              '',
    'Name':              '',
    'Email':             '',
    'Gdrive access':     '',
    'SKU':               'NO SALE THIS MONTH',
    'Listing Price':     '',
    '3DPS+Stripe Fee':   '',
    'Payment Complete':  '',
    'Date of Payment':   '',
    'Remarks':           'NO SALE',
  };
  placeholder[takehomeCol] = '';
  // Reorder to canonical 12-col
  const ordered = {
    'Order No.':         placeholder['Order No.'],
    'Date':              placeholder['Date'],
    'Name':              placeholder['Name'],
    'Email':             placeholder['Email'],
    'Gdrive access':     placeholder['Gdrive access'],
    'SKU':               placeholder['SKU'],
    'Listing Price':     placeholder['Listing Price'],
    '3DPS+Stripe Fee':   placeholder['3DPS+Stripe Fee'],
    [takehomeCol]:       placeholder[takehomeCol],
    'Payment Complete':  placeholder['Payment Complete'],
    'Date of Payment':   placeholder['Date of Payment'],
    'Remarks':           placeholder['Remarks'],
  };
  return [{ json: ordered, pairedItem: { item: 0 } }];
}
return orderedRows.map(r => ({ json: r, pairedItem: { item: 0 } }));

// ============ Sign JWT + Get Token + Apply Format + Move Tab to Front ============
// Uses Node.js fs + crypto + https (N8N_RUNNERS_ENABLED=false confirmed unblocks these).
// Must be a Code node, not HTTP nodes, because the SA private key is read from disk.

const fs = require('fs');
const crypto = require('crypto');
const https = require('https');

function b64u(buf) { return Buffer.from(buf).toString('base64').replace(/=+$/,'').replace(/\+/g,'-').replace(/\//g,'_'); }
function signJWT(saJson, scope) {
  const now = Math.floor(Date.now() / 1000);
  const header  = { alg: 'RS256', typ: 'JWT' };
  const payload = { iss: saJson.client_email, scope, aud: 'https://oauth2.googleapis.com/token', exp: now + 3600, iat: now };
  const signingInput = b64u(JSON.stringify(header)) + '.' + b64u(JSON.stringify(payload));
  const signer = crypto.createSign('RSA-SHA256');
  signer.update(signingInput);
  const sig = signer.sign(saJson.private_key);
  return signingInput + '.' + b64u(sig);
}
function httpsRequestRaw(opts, body) {
  return new Promise((resolve, reject) => {
    const req = https.request(opts, res => {
      let data = ''; res.on('data', c => data += c);
      res.on('end', () => resolve({ statusCode: res.statusCode, body: data }));
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}
async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }
async function httpsRequest(opts, body) {
  // Retry on 429/5xx with exponential backoff
  const maxTries = 5;
  for (let attempt = 0; attempt < maxTries; attempt++) {
    const res = await httpsRequestRaw(opts, body);
    if (res.statusCode !== 429 && res.statusCode < 500) return res;
    if (attempt === maxTries - 1) return res;
    const wait = Math.min(2000 * Math.pow(2, attempt), 30000);
    await sleep(wait);
  }
}
async function getAccessToken(saJson) {
  const jwt = signJWT(saJson, 'https://www.googleapis.com/auth/spreadsheets');
  const body = 'grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=' + encodeURIComponent(jwt);
  const res = await httpsRequest({
    hostname: 'oauth2.googleapis.com', path: '/token', method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'Content-Length': Buffer.byteLength(body) },
  }, body);
  if (res.statusCode !== 200) throw new Error('Token fetch failed: ' + res.statusCode + ' ' + res.body);
  return JSON.parse(res.body).access_token;
}
async function getSheetId(token, spreadsheetId, tabName) {
  const path = '/v4/spreadsheets/' + spreadsheetId + '?fields=sheets.properties';
  const res = await httpsRequest({
    hostname: 'sheets.googleapis.com', path, method: 'GET',
    headers: { 'Authorization': 'Bearer ' + token },
  });
  if (res.statusCode !== 200) throw new Error('Sheet meta fetch failed: ' + res.statusCode + ' ' + res.body);
  const meta = JSON.parse(res.body);
  for (const s of (meta.sheets || [])) {
    if (s.properties && s.properties.title === tabName) return s.properties.sheetId;
  }
  throw new Error('Tab not found: ' + tabName);
}
async function batchUpdate(token, spreadsheetId, body) {
  const json = JSON.stringify(body);
  const res = await httpsRequest({
    hostname: 'sheets.googleapis.com',
    path: '/v4/spreadsheets/' + spreadsheetId + ':batchUpdate',
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(json) },
  }, json);
  if (res.statusCode !== 200) throw new Error('batchUpdate failed: ' + res.statusCode + ' ' + res.body);
  return JSON.parse(res.body);
}

// ----- Main -----
const trigger = $('Workflow Trigger').first().json;
const saPath = $env.N8N_GOOGLE_SA_JSON || '/files/sa.json';
const saJson = JSON.parse(fs.readFileSync(saPath, 'utf8'));
const spreadsheetId = trigger.params.INTERNAL_SHEET_ID;
const tabName = trigger.supplier.dest_tab_name;

const ORANGE = { red: 1.0,  green: 0.78, blue: 0.49 };  // Walkin / non-numeric Order No.
const YELLOW = { red: 1.0,  green: 0.94, blue: 0.62 };  // TITLE MATCH or UNDERPRICED
const RED    = { red: 1.0,  green: 0.78, blue: 0.78 };  // REFUND or CURRENCY
const PURPLE = { red: 0.85, green: 0.75, blue: 0.95 };  // MANUAL ENTRY (human-input rows)
const TEAL   = { red: 0.70, green: 0.90, blue: 0.95 };  // CANCELLED order — verify

try {
  const token   = await getAccessToken(saJson);
  const sheetId = await getSheetId(token, spreadsheetId, tabName);

  // Discover existing CF rules so we can delete them (idempotent)
  const metaPath = '/v4/spreadsheets/' + spreadsheetId + '?ranges=' + encodeURIComponent("'" + tabName + "'!A1") + '&fields=sheets.conditionalFormats';
  const metaRes = await httpsRequest({ hostname: 'sheets.googleapis.com', path: metaPath, method: 'GET', headers: { 'Authorization': 'Bearer ' + token } });
  let existingRules = [];
  if (metaRes.statusCode === 200) {
    const m = JSON.parse(metaRes.body);
    for (const s of (m.sheets || [])) if (s.conditionalFormats) existingRules = s.conditionalFormats;
  }

  const range = { sheetId, startRowIndex: 1, startColumnIndex: 0, endColumnIndex: 12 };
  const requests = [];
  // Move tab to leftmost
  requests.push({ updateSheetProperties: { properties: { sheetId, index: 0 }, fields: 'index' } });
  // Highlight header row (row 1) light grey + bold
  requests.push({ repeatCell: {
    range: { sheetId, startRowIndex: 0, endRowIndex: 1, startColumnIndex: 0, endColumnIndex: 12 },
    cell: { userEnteredFormat: { backgroundColor: { red: 0.85, green: 0.85, blue: 0.85 }, textFormat: { bold: true } } },
    fields: 'userEnteredFormat(backgroundColor,textFormat)',
  } });
  // Delete existing CF rules in reverse order
  for (let i = existingRules.length - 1; i >= 0; i--) {
    requests.push({ deleteConditionalFormatRule: { sheetId, index: i } });
  }
  // Rule order matters — first matching rule wins. Higher-priority categories must come first.
  // Index 0: PURPLE — MANUAL ENTRY (human-input rows like fedex deductions)
  requests.push({ addConditionalFormatRule: { rule: {
    ranges: [range],
    booleanRule: {
      condition: { type: 'CUSTOM_FORMULA', values: [{ userEnteredValue: '=REGEXMATCH($L2,"MANUAL ENTRY")' }] },
      format: { backgroundColor: PURPLE },
    },
  }, index: 0 } });
  // Index 1: TEAL — CANCELLED order (kept for verification)
  requests.push({ addConditionalFormatRule: { rule: {
    ranges: [range],
    booleanRule: {
      condition: { type: 'CUSTOM_FORMULA', values: [{ userEnteredValue: '=REGEXMATCH($L2,"CANCELLED")' }] },
      format: { backgroundColor: TEAL },
    },
  }, index: 1 } });
  // Index 2: RED — REFUND or CURRENCY (errors)
  requests.push({ addConditionalFormatRule: { rule: {
    ranges: [range],
    booleanRule: {
      condition: { type: 'CUSTOM_FORMULA', values: [{ userEnteredValue: '=OR(REGEXMATCH($L2,"REFUND"),REGEXMATCH($L2,"CURRENCY"))' }] },
      format: { backgroundColor: RED },
    },
  }, index: 2 } });
  // Index 3: YELLOW — TITLE MATCH or UNDERPRICED (warnings)
  requests.push({ addConditionalFormatRule: { rule: {
    ranges: [range],
    booleanRule: {
      condition: { type: 'CUSTOM_FORMULA', values: [{ userEnteredValue: '=OR(REGEXMATCH($L2,"TITLE MATCH"),REGEXMATCH($L2,"UNDERPRICED"))' }] },
      format: { backgroundColor: YELLOW },
    },
  }, index: 3 } });
  // Index 4: ORANGE — non-numeric Order No. (covers Walkin, Cash IFB, blanks)
  requests.push({ addConditionalFormatRule: { rule: {
    ranges: [range],
    booleanRule: {
      condition: { type: 'CUSTOM_FORMULA', values: [{ userEnteredValue: '=AND($A2<>"", NOT(ISNUMBER(VALUE($A2))))' }] },
      format: { backgroundColor: ORANGE },
    },
  }, index: 4 } });

  await batchUpdate(token, spreadsheetId, { requests });
  return [{ json: { format_status: 'success', tab: tabName, sheet_id_inner: sheetId, requests_applied: requests.length } }];
} catch (e) {
  return [{ json: { format_status: 'error', tab: tabName, error: String(e && e.message || e) } }];
}

// Build a Run Log row for THIS supplier from Match output + format result.
const trigger    = $('Workflow Trigger').first().json;
const supplier   = trigger.supplier || {};
const matchItems = $('Match SKUs & Build Rows').all().map(it => it.json);
const rowsBuilt  = matchItems.filter(j => j && j['Order No.'] !== undefined).length;
const orders     = trigger.orders || [];
const lineItemCount = orders.reduce((acc, o) => acc + ((o.line_items || []).length), 0);
const walkinTotal = $('Read Walkin Source').all().filter(it => it.json && Object.keys(it.json).length > 0).length;
function countFlag(needle) {
  return matchItems.filter(r => r && (r['Remarks'] || '').includes(needle)).length;
}
const formatResult = $('Apply Format + Tab Front').first().json;
// TZ-SAFE timestamp (Asia/Singapore). The JS Task Runner does not inherit TZ from
// the container and evaluates as UTC, so getHours()/getDate() previously logged UTC
// -- e.g. the 1 Aug 02:00 SGT cron was recorded as '2026-07-31 18:00'. SGT is UTC+8
// year-round, so shift the instant then read UTC parts.
const now = new Date(Date.now() + 8 * 3600 * 1000);
const pad = n => String(n).padStart(2, '0');
const tsStr = now.getUTCFullYear() + '-' + pad(now.getUTCMonth()+1) + '-' + pad(now.getUTCDate()) + ' ' + pad(now.getUTCHours()) + ':' + pad(now.getUTCMinutes()) + ':' + pad(now.getUTCSeconds());
const walkinKept = matchItems.filter(r => r && String(r['Order No.'] || '').trim() && !/^\d+$/.test(String(r['Order No.']).trim())).length;
return [{ json: {
  'timestamp':           tsStr,
  'supplier':            supplier.supplier_name || '',
  'tab':                 supplier.dest_tab_name || '',
  'shopify_orders':      orders.length,
  'shopify_line_items':  lineItemCount,
  'walkin_total':        walkinTotal,
  'rows_built':          rowsBuilt,
  'walkin_in_dest':      walkinKept,
  'flagged_currency':    countFlag('CURRENCY'),
  'flagged_refund':      countFlag('REFUND'),
  'flagged_underprice':  countFlag('UNDERPRICED'),
  'flagged_title_match': countFlag('TITLE MATCH'),
  'format_status':       (formatResult && formatResult.format_status) || 'unknown',
  'format_error':        (formatResult && formatResult.error) || '',
  'status':              'success'
}}];
